"""Replay a logged app request with tools that its history calls removed from the tool list."""
import copy, json, os, sys, urllib.request, urllib.error

LOG = sys.argv[1]
REMOVED = {"printer_bambu_connect", "printer_connection_status"}
conf = json.load(open(os.path.expanduser("~/Library/Application Support/JusPrin2/JusPrin2.conf")))["jusprin_agent"]
body = json.load(open(LOG))["body"]


def post(url, headers, payload):
    req = urllib.request.Request(url, json.dumps(payload).encode(), {"Content-Type": "application/json", **headers})
    try:
        with urllib.request.urlopen(req, timeout=180) as r:
            return r.status, json.load(r)
    except urllib.error.HTTPError as e:
        return e.code, e.read().decode()[:600]


def responses_summary(result):
    if not isinstance(result, dict):
        return result
    out = []
    for item in result.get("output", []):
        if item.get("type") == "function_call":
            out.append(f"call {item['name']}({item.get('arguments')})")
        elif item.get("type") == "message":
            out.append("text: " + " ".join(p.get("text", "") for p in item["content"])[:160])
    return f"status={result.get('status')} usage={result.get('usage', {}).get('input_tokens')}in | " + " ; ".join(out)


def responses_variants(drop_web_search):
    base = copy.deepcopy(body)
    base["stream"] = False
    if drop_web_search:
        base["tools"] = [t for t in base["tools"] if t.get("type") == "function"]
    removed = copy.deepcopy(base)
    removed["tools"] = [t for t in base["tools"] if t.get("name") not in REMOVED]
    return base, removed


def anthropic_request(responses_body, tools):
    system = responses_body["instructions"]
    messages = []

    def add(role, block):
        if messages and messages[-1]["role"] == role:
            messages[-1]["content"].append(block)
        else:
            messages.append({"role": role, "content": [block]})

    for item in responses_body["input"]:
        kind = item.get("type") or "message"
        role = item.get("role")
        if kind == "function_call":
            add("assistant", {"type": "tool_use", "id": item["call_id"], "name": item["name"],
                              "input": json.loads(item["arguments"])})
        elif kind == "function_call_output":
            add("user", {"type": "tool_result", "tool_use_id": item["call_id"],
                         "content": [{"type": "text", "text": item["output"]}]})
        elif role == "developer":
            system += "\n\n" + "".join(p.get("text", "") for p in item["content"]) if isinstance(item["content"], list) else item["content"]
        else:
            text = "".join(p.get("text", "") for p in item["content"])
            add("assistant" if role == "assistant" else "user", {"type": "text", "text": text})
    return {"model": "claude-opus-5-5", "max_tokens": 2048, "system": system, "messages": messages,
            "tools": [{"name": t["name"], "description": t.get("description", ""), "input_schema": t["parameters"]}
                      for t in tools if t.get("type") == "function"]}


def anthropic_summary(result):
    if not isinstance(result, dict):
        return result
    out = []
    for block in result.get("content", []):
        if block["type"] == "tool_use":
            out.append(f"call {block['name']}({json.dumps(block['input'])})")
        elif block["type"] == "text":
            out.append("text: " + block["text"][:160])
    return f"stop={result.get('stop_reason')} usage={result.get('usage', {}).get('input_tokens')}in | " + " ; ".join(out)


runs = []
orb, orb_removed = responses_variants(False)
for model in ["openai/gpt-5.4-mini", "deepseek/deepseek-v4-flash"]:
