// Every provider this build can talk to, in the order setup lists them.
inline const std::vector<ProviderProfile>& provider_profiles()
{
    static const std::vector<ProviderProfile> rows{
        // JusPrin's own gateway. Its models are aliases ("slicer-1") that the
        // gateway maps to a provider's model, and each alias says which wire
        // format it is served in; account_profile() turns this row into the
        // one a chat talks to. max_tokens serves the Anthropic format.
        // The server the account signs in to is derived from this endpoint.
        // It is JusPrin's host, not Obico's: the server decides by host which
        // brand's accounts a sign-in uses, and JusPrin's are its own.
        {"jusprin", ProviderFamily::Responses, "https://jusprinv2.obico.io/ent/jusprin/v2/responses", AuthStyle::Bearer,
         "slicer-1", "JusPrin", {}, 64000, {}, true},
        {"openai", ProviderFamily::Responses, "https://api.openai.com/v1/responses", AuthStyle::Bearer, "gpt-5.4-mini", "OpenAI", {}, 0},
        // OpenRouter serves the Responses API. The default is the model the
        // OpenAI row uses, so the behaviour is the one already evaluated.
        // X-Title names the app in OpenRouter's usage pages. OpenRouter
        // also reads HTTP-Referer, the app's website, to give it a page of
        // its own; this build has no website constant to send, so it sends
        // none. Its web search is a tool of its own, for any model it serves.
        {"openrouter", ProviderFamily::Responses, "https://openrouter.ai/api/v1/responses", AuthStyle::Bearer,
        })
        .on_error([cancelled, finished](std::string, std::string, unsigned) {
            if (!*cancelled)
                (*finished)(std::nullopt);
        })
        .perform();
}

void fetch_account_box(const ProviderProfile& profile, const std::string& token, const std::string& url,
                       std::shared_ptr<std::atomic<bool>> cancelled, std::function<void(std::optional<std::string>)> done)
{
    auto finished = std::make_shared<std::function<void(std::optional<std::string>)>>(std::move(done));
    auto http     = Slic3r::Http::get(url);
    if (!token.empty())
        http.header("Authorization", "Bearer " + token);
    for (const AgentHttpHeader& header : profile.headers)
        http.header(header.name, header.value);
    http.header("Accept", "text/html")
        .tls_verify(true)
        .timeout_connect(10)
        .timeout_max(30)
        .on_progress([cancelled](Slic3r::Http::Progress, bool& cancel) { cancel = *cancelled; })
        .on_complete([cancelled, finished](std::string body, unsigned status) {
            if (*cancelled)
                return;
            // 204, and anything but HTML, is no box.
            (*finished)(status == 200 && !body.empty() ? std::optional<std::string>(std::move(body)) : std::nullopt);
        })
        .on_error([cancelled, finished](std::string, std::string, unsigned) {
            if (!*cancelled)
                (*finished)(std::nullopt);
        })
        .perform();
}

