"""Which JusPrin releases the server still serves.

Every request JusPrin's own code sends names its release in the User-Agent:
"JusPrin/<release> OrcaSlicer/<OrcaSlicer release>". A release older than
JUSPRIN_V2_MIN_APP_VERSION gets 426 update_required from every endpoint the
app calls itself, so the app can tell the person to update instead of
failing in some other way. An empty setting serves every release.

A User-Agent without the OrcaSlicer token names no JusPrin release and is
served as before: builds made before the app named its release sent
OrcaSlicer's version after "JusPrin/", and the pages the app opens in a
browser send the browser's.
"""
import re
from functools import wraps

from django.conf import settings
from django.http import HttpResponse

from .errors import GatewayError

RELEASE = re.compile(r'(?:^|\s)JusPrin/(\d+)\.(\d+)\.(\d+)(?=\s)')
ORCASLICER = re.compile(r'(?:^|\s)OrcaSlicer/\S')


def _release(text: str):
    return tuple(int(part) for part in text.split('.'))


def app_release(user_agent: str):
    """The JusPrin release the User-Agent names, as (major, minor, patch), or None."""
    if not user_agent or not ORCASLICER.search(user_agent):
        return None
    found = RELEASE.search(user_agent)
    return tuple(int(part) for part in found.groups()) if found else None


def refusal(user_agent: str):
    """The update_required answer for a release the server no longer serves, or None."""
    minimum = settings.JUSPRIN_V2_MIN_APP_VERSION
    release = app_release(user_agent)
    if not minimum or release is None or release >= _release(minimum):
        return None
    return GatewayError(426, 'update_required', details={'minimumVersion': minimum})


def supported_app(view):
    """Answers a request from a release the server no longer serves with update_required."""
    @wraps(view)
    def checked(request, *args, **kwargs):
        error = refusal(request.headers.get('User-Agent', ''))
        if error is not None:
            return HttpResponse(error.body(), status=error.status, content_type='application/json')
        return view(request, *args, **kwargs)
    return checked

