"""A JusPrin release older than JUSPRIN_V2_MIN_APP_VERSION is told to update by
every endpoint the app calls itself, and only a User-Agent that names a JusPrin
release is judged."""
import json

import httpx
from django.test import Client, SimpleTestCase, override_settings

from jusprin.v2.app_version import app_release
from jusprin.v2.asgi import application

from .test_gateway import GatewayTestCase

OLD = 'JusPrin/2.0.0 OrcaSlicer/2.5.0'
CURRENT = 'JusPrin/2.1.0 OrcaSlicer/2.5.0'


class AppReleaseTests(SimpleTestCase):
    def test_the_release_comes_from_the_jusprin_token_beside_orcaslicer(self):
        self.assertEqual(app_release(OLD), (2, 0, 0))
        self.assertEqual(app_release('OrcaSlicer/2.5.0 JusPrin/2.10.3 extra'), (2, 10, 3))

    def test_a_user_agent_without_the_orcaslicer_token_names_no_release(self):
        # Builds before the app named its release sent OrcaSlicer's version here.
        self.assertIsNone(app_release('JusPrin/2.5.0'))
        self.assertIsNone(app_release('Mozilla/5.0 (Macintosh) AppleWebKit/605.1.15'))
        self.assertIsNone(app_release(''))
        self.assertIsNone(app_release(None))

    def test_a_release_that_is_not_three_numbers_names_none(self):
        self.assertIsNone(app_release('JusPrin/2.0 OrcaSlicer/2.5.0'))
        self.assertIsNone(app_release('JusPrin/2.0.0-beta OrcaSlicer/2.5.0'))


@override_settings(JUSPRIN_V2_MIN_APP_VERSION='2.1.0')
class DjangoEndpointTests(SimpleTestCase):
    databases = '__all__'

    def ask(self, method, path, user_agent):
        call = getattr(Client(), method)
        return call(f'/ent/jusprin/v2/{path}', HTTP_USER_AGENT=user_agent, **(
            {'data': '{}', 'content_type': 'application/json'} if method == 'post' else {}))

    def test_every_endpoint_the_app_calls_tells_an_old_release_to_update(self):
        for method, path in [('get', 'models'), ('get', 'account'), ('get', 'account_box'), ('post', 'print_reports'),
                             ('post', 'web_link'), ('post', 'auth/code/request'), ('post', 'auth/code/confirm'),
                             ('post', 'auth/login')]:
            with self.subTest(path=path):
                response = self.ask(method, path, OLD)
                self.assertEqual(response.status_code, 426)
                self.assertEqual(response.json(), {
                    'type': 'error',
                    'error': {'code': 'update_required',
                              'message': 'This version of JusPrin is no longer supported. Update JusPrin to keep using it.'},
                    'minimumVersion': '2.1.0'})

    def test_a_served_release_and_an_unnamed_one_reach_the_endpoint(self):
        for user_agent in (CURRENT, 'JusPrin/3.0.0 OrcaSlicer/2.6.0', 'JusPrin/2.5.0', ''):
            with self.subTest(user_agent=user_agent):
                # No token: the endpoint's own answer, not the update.
                self.assertEqual(self.ask('get', 'models', user_agent).status_code, 401)

    def test_the_pages_the_app_opens_in_a_browser_are_not_judged(self):
        self.assertNotEqual(self.ask('get', 'web/done', OLD).status_code, 426)

    @override_settings(JUSPRIN_V2_MIN_APP_VERSION='')
    def test_with_no_minimum_every_release_is_served(self):
        self.assertEqual(self.ask('get', 'models', OLD).status_code, 401)


