// state 'failed' with error code 'stale_workspace' ('stale_revision' in chats
// saved before the codes were unified).
export type ToolStateName =
  | 'running'
  | 'succeeded'
  | 'failed'
  | 'cancelled';

export type ActionClassName = 'read_only' | 'mutation' | 'destructive';

// Work the application ran outside the chat: a slice, an arrange, an export.
// Saved with the project at the place in the timeline where it started
// (`afterId`), and completed in place. `interrupted` is an entry that was
// still running when its project was closed.
export type WorkStateName = 'running' | 'done' | 'cancelled' | 'failed' | 'interrupted';

export interface WorkInfo {
  seq: number;
  id: string;
  startedAt: string;
  running: 'Running…',
  succeeded: 'Done',
  failed: 'The action failed.',
  cancelled: 'Cancelled — nothing was changed',
};

// Which glyph a state's line leads with. Colour is never the only signal: the
// line always has its icon and its words.
const stateIcons: Record<ToolStateName, string> = {
  running: 'running',
  succeeded: 'done',
  failed: 'failed',
  cancelled: 'cancelled',
};

// The one status line every state of a tool card has.
export function ToolStatus({ state, children }: { state: ToolStateName; children: ReactNode }) {
  return (
    <div className={`tool-state ${stateIcons[state]}`}>
      <span className={`tool-status-icon ${stateIcons[state]}`} aria-hidden="true" />
      <span className="tool-state-text">{children}</span>
    </div>
  );
}

